@Test
public void testTrimComment_1_oe() {
    assertEquals("Wrong trimmed comment","This is a comment" + CR + "that spans multiple" + CR + "lines in a" + CR + " complex way.",PropertiesConfigurationLayout.trimComment(" # This is a comment" + CR + "that spans multiple" + CR + "!lines in a" + CR + " complex way.",false));
}

mut_method_definition:
static String trimComment(final String s, final boolean comment) {
        final StringBuilder buf = new StringBuilder(s.length());
        int lastPos = 0;
        int pos;

        do {
            pos = s.indexOf(CR, lastPos);
            if (pos >= 0) {
                final String line = s.substring(lastPos, pos);
                buf.append(stripCommentChar(line, comment)).append(CR);
                lastPos = pos + CR.length();
            }
        } while (pos >= 0);

        if (lastPos < s.length()) {
            buf.append(stripCommentChar(s.substring(lastPos), comment));
        }
        return buf.toString();
    }

