public boolean isAttributeKey(final String key) {
        if (key == null) {
            return false;
        }

        return key.startsWith(getSymbols().getAttributeStart()) && (getSymbols().getAttributeEnd() == null || key.endsWith(getSymbols().getAttributeEnd()));
    }

