public String trimRight(final String key) {
        if (key == null) {
            return StringUtils.EMPTY;
        }
        String result = key;
        while (hasTrailingDelimiter(result)) {
            result = result.substring(0, result.length() - getSymbols().getPropertyDelimiter().length());
        }
        return result;
    }

