mut_method_definition:
String quoteString(String s) {
        if (s == null) {
            return null;
        }

        if (s.indexOf(' ') != -1 || s.indexOf('\t') != -1 || s.indexOf('\r') != -1 || s.indexOf('\n') != -1 || s.indexOf('"') != -1 || s.indexOf('(') != -1
            || s.indexOf(')') != -1 || s.indexOf('{') != -1 || s.indexOf('}') != -1 || s.indexOf('=') != -1 || s.indexOf(',') != -1 || s.indexOf(';') != -1) {
            s = s.replace("\"", "\\\"");
            s = "\"" + s + "\"";
        }

        return s;
    }

